1	import type { AITask } from "@/components/smoothui/ai-task-list";
2	import type { AIDiffLine } from "@/components/smoothui/ai-diff";
3	import type { ModelCall, RunResult, RunSummary, Step } from "./api";
4	
5	export type StatusMeta = { word: string; glyph: string; tone: string; text: string };
6	
7	// Every state is a word plus a glyph; colour is never the only signal.
8	const T_RUNS = "bg-runs-soft text-runs";
9	const T_GAPS = "bg-gaps-soft text-gaps";
10	const T_BROKEN = "bg-broken-soft text-broken";
11	const T_CHECK = "bg-checking-soft text-checking";
12	const STATUS: Record<string, StatusMeta> = {
13	  runs: { word: "Runs", glyph: "✓", tone: T_RUNS, text: "text-runs" },
14	  runs_with_gaps: { word: "Runs with gaps", glyph: "◐", tone: T_GAPS, text: "text-gaps" },
15	  // The fix passed in the clean container but changes code and waits for the owner. Dashed outline, so
16	  // it can't be read as a clean pass (solid green) or as "Runs with gaps" (solid amber).
17	  fix_awaiting_approval: {
18	    word: "Fix verified · awaiting approval",
19	    glyph: "◆",
20	    tone: "border border-dashed border-gaps bg-gaps-soft text-gaps",
21	    text: "text-gaps",
22	  },
23	  // The patch only excluded tests. Styled like broken: it is not a repair.
24	  fix_skipped_tests: { word: "Fix skipped tests · not a repair", glyph: "✗", tone: T_BROKEN, text: "text-broken" },
25	  broken: { word: "Broken", glyph: "✗", tone: T_BROKEN, text: "text-broken" },
26	  fail: { word: "Broken", glyph: "✗", tone: T_BROKEN, text: "text-broken" },
27	  // Only a record with no verifier steps at all lands here (see api/main.py).
28	  fixed: { word: "Fixed, unverified", glyph: "◐", tone: T_GAPS, text: "text-gaps" },
29	  checking: { word: "Checking", glyph: "◌", tone: T_CHECK, text: "text-checking" },
30	  model_limited: { word: "Model limit reached", glyph: "◌", tone: T_BROKEN, text: "text-broken" },
31	  unsupported: { word: "Unsupported", glyph: "◌", tone: "bg-muted text-secondary", text: "text-secondary" },
32	};
33	
34	export const statusMeta = (status: string): StatusMeta =>
35	  STATUS[status] ?? { word: "Unknown", glyph: "?", tone: "bg-muted text-secondary", text: "text-secondary" };
36	
37	export function fmtDur(s: number | null | undefined): string {
38	  if (s == null) return "—";
39	  if (s < 60) return `${s.toFixed(s < 10 ? 1 : 0)}s`;
40	  const m = Math.floor(s / 60);
41	  return `${m}m ${String(Math.round(s % 60)).padStart(2, "0")}s`;
42	}
43	
44	export const shortRepo = (repo: string | null) => (repo ? repo.split("/")[1] ?? repo : "—");
45	
46	export function fmtWhen(ts: number | null | undefined): string {
47	  if (!ts) return "";
48	  return new Date(ts * 1000).toLocaleString("en-GB", {
49	    day: "numeric", month: "short", hour: "2-digit", minute: "2-digit", timeZone: "UTC",
50	  }) + " UTC";
51	}
52	
53	export const fixLabel = (kind: string | null, needsApproval: boolean) =>
54	  kind === "code" ? (needsApproval ? "Code · needs approval" : "Code") : kind === "config" ? "Config" : "None";
55	
56	export const stepOk = (s: Step) => s.exit_code === 0;
57	
58	/** A run that may be shown as an example: it has a record and its fix did not just skip tests. */
59	export const isShowable = (r: RunSummary) => r.status !== "checking" && r.status !== "fix_skipped_tests" && !r.weakens_tests;
60	
61	/** Latest verified run, preferring a config fix, then any fix; otherwise the latest showable run. */
62	export function pickFeatured(runs: RunSummary[]): RunSummary | null {
63	  const real = runs.filter(isShowable);
64	  return (
65	    real.find((r) => r.status === "runs" && r.fix_kind === "config") ??
66	    real.find((r) => r.status === "runs" && r.fix_kind) ??
67	    real.find((r) => r.status === "runs") ??
68	    real[0] ??
69	    null
70	  );
71	}
72	
73	/** "Held-out set, agent v1": which evaluation set and agent produced a record, as far as it says. */
74	export function runTag(r: Pick<RunSummary, "set" | "agent_version">): string | null {
75	  const set = r.set === "heldout" ? "Held-out set" : r.set === "dev" ? "Development repos" : null;
76	  const agent = r.agent_version ? `agent ${r.agent_version}` : null;
77	  return [set, agent].filter(Boolean).join(", ") || null;
78	}
79	
80	/** Latest run per repo (the list is newest first). */
81	export function latestPerRepo(runs: RunSummary[]): RunSummary[] {
82	  const seen = new Set<string>();
83	  const out: RunSummary[] = [];
84	  for (const r of runs) {
85	    const key = `${r.repo}|${r.path}`;
86	    if (!r.repo || r.status === "checking" || seen.has(key)) continue;
87	    seen.add(key);
88	    out.push(r);
89	  }
90	  return out;
91	}
92	
93	export type ReplayEvent =
94	  | { kind: "step"; side: "agent" | "verifier"; step: Step }
95	  | { kind: "model"; call: ModelCall };
96	
97	/** Recorded steps in order, with each model call placed where it started. */
98	export function buildEvents(result: RunResult): ReplayEvent[] {
99	  const calls = [...(result.model_calls ?? [])].sort((a, b) => (a.started ?? 0) - (b.started ?? 0));
100	  const events: ReplayEvent[] = [];
101	  let ci = 0;
102	  const flushCalls = (before: number | undefined) => {
103	    while (ci < calls.length && (before === undefined || (calls[ci].started ?? 0) < before)) {
104	      events.push({ kind: "model", call: calls[ci++] });
105	    }
106	  };
107	  for (const step of result.agent?.steps ?? []) {
108	    if (step.started !== undefined) flushCalls(step.started);
109	    events.push({ kind: "step", side: "agent", step });
110	  }
111	  flushCalls(undefined);
112	  for (const step of result.verifier?.steps ?? []) events.push({ kind: "step", side: "verifier", step });
113	  return events;
114	}
115	
116	/** The agent's plan as a task list: each stage it ran, its repair attempts, then the verifier. */
117	export function buildTasks(result: RunResult): AITask[] {
118	  const steps = result.agent?.steps ?? [];
119	  const order: string[] = [];
120	  const last = new Map<string, Step>();
121	  for (const s of steps) {
122	    if (!last.has(s.name)) order.push(s.name);
123	    last.set(s.name, s);
124	  }
125	  const attempts = result.agent?.attempts ?? [];
126	  const tasks: AITask[] = order.map((name, i) => {
127	    const s = last.get(name)!;
128	    const runs = steps.filter((x) => x.name === name).length;
129	    return {
130	      id: `stage-${i}`,
131	      label: STAGE_LABEL[name] ?? name,
132	      status: stepOk(s) ? "done" : "failed",
133	      note: runs > 1 ? `${runs} runs` : fmtDur(s.duration_s),
134	    };
135	  });
136	  // Repairs hang off the first stage that ever failed, even if a later attempt got it through.
137	  const firstFailed = steps.find((s) => !stepOk(s));
138	  const failedStage = firstFailed ? tasks[order.indexOf(firstFailed.name)] : undefined;
139	  const repairs: AITask[] = attempts.map((a, i) => ({
140	    id: `fix-${i}`,
141	    label: `Repair ${i + 1}: ${a.kind ?? "fix"} in ${(a.files ?? []).join(", ") || "—"}`,
142	    status: a.status === "needs_approval" ? "pending" : a.result === "passed" ? "done" : "failed",
143	    note: a.status === "needs_approval" ? "needs approval" : undefined,
144	  }));
145	  if (repairs.length) {
146	    const target = failedStage ?? tasks[tasks.length - 1];
147	    if (target) target.children = repairs;
148	    else tasks.push(...repairs);
149	  }
150	  const v = result.verifier?.steps ?? [];
151	  tasks.push({
152	    id: "verify",
153	    label: "Rebuild in a separate clean container",
154	    status: v.length === 0 ? "pending" : v.every(stepOk) ? "done" : "failed",
155	    note: v.length === 0 ? "not reached" : fmtDur(v.reduce((a, s) => a + (s.duration_s ?? 0), 0)),
156	  });
157	  return tasks;
158	}
