4	/** True once the element has scrolled into view (and stays true). Always true under reduced motion. */
5	export function useInView<T extends Element>(margin = "0px 0px -12% 0px") {
6	  const reduce = useReducedMotion();
7	  const ref = useRef<T>(null);
8	  const [seen, setSeen] = useState(false);
9	  useEffect(() => {
10	    if (reduce || typeof IntersectionObserver === "undefined") {
11	      setSeen(true);
12	      return;
13	    }
14	    const el = ref.current;
15	    if (!el) return;
16	    const io = new IntersectionObserver(
17	      ([e]) => {
18	        if (e.isIntersecting) {
19	          setSeen(true);
20	          io.disconnect();
21	        }
22	      },
23	      { rootMargin: margin },
24	    );
25	    io.observe(el);
26	    return () => io.disconnect();
27	  }, [reduce, margin]);
28	  return { ref, on: seen || !!reduce };
29	}
