19	type Line = { text: string; tone?: "bad" | "added" | "muted" | "good" };
20	type Stat = { label: string; value: string };
21	type Content = { title: string; lines: Line[]; stats: Stat[] };
22	
23	const ERROR_LINE = /error|ERR_|failed|timed out|fatal|exit code|cannot|not found|ignored build/i;
24	
25	/** Real excerpt and real stat cards for one tab. A stat with no measurement is simply left out. */
26	function contentFor(tab: TabKey, d: RunDetail): Content {
27	  const r = d.result;
28	  const steps = r.agent?.steps ?? [];
29	  const attempts = r.agent?.attempts ?? [];
30	  const calls = r.model_calls ?? [];
31	  const stats: Stat[] = [];
32	  const add = (label: string, value: string | number | null | undefined) => {
33	    if (value !== null && value !== undefined && value !== "" && value !== "—") stats.push({ label, value: String(value) });
34	  };
35	
36	  if (tab === "check") {
37	    const failIdx = steps.findIndex((s) => !stepOk(s));
38	    const upTo = failIdx >= 0 ? steps.slice(0, failIdx + 1) : steps;
39	    const failed = failIdx >= 0 ? steps[failIdx] : null;
40	    const lines: Line[] = [];
41	    if (failed) {
42	      lines.push({ text: `$ ${failed.command}`, tone: "muted" });
43	      const tail = (failed.output_tail ?? []).map(cleanLine).filter((l) => l.trim());
44	      const errs = tail.filter((l) => ERROR_LINE.test(l));
45	      for (const l of (errs.length ? errs : tail.slice(-3)).slice(0, 5)) lines.push({ text: l, tone: "bad" });
46	    } else {
47	      for (const s of steps) lines.push({ text: `✓ ${s.name}  ${fmtDur(s.duration_s)}`, tone: "good" });
48	    }
49	    add(failed ? "Steps before it stopped" : "Steps passed", upTo.length || null);
50	    add(failed ? "Time to the first failure" : "Time in the agent container", fmtDur(upTo.reduce((a, s) => a + (s.duration_s ?? 0), 0)));
51	    add("Stopped at", failed?.name);
52	    return { title: `${r.repo} · check`, lines, stats };
53	  }
54	
55	  if (tab === "diagnose") {
56	    const a = attempts[0];
57	    const lines: Line[] = a?.rationale
58	      ? [{ text: `“${a.rationale}”` }]
59	      : r.agent?.rules_fired?.length
60	        ? [{ text: `Rule fired: ${r.agent.rules_fired[0]}. No model call was needed.` }]
61	        : [{ text: "This run needed no diagnosis." }];
62	    add("Model calls", calls.length || null);
63	    add("Time thinking", calls.length ? fmtDur(calls.reduce((s, c) => s + (c.duration_s ?? 0), 0)) : null);
64	    add("Confidence", a?.confidence != null ? a.confidence.toFixed(2) : null);
65	    add("Model", calls.find((c) => c.model)?.model);
66	    return { title: `${r.repo} · diagnose`, lines, stats };
67	  }
68	
69	  if (tab === "repair") {
70	    const files = d.fix_patch ? parsePatch(d.fix_patch) : [];
71	    const lines: Line[] = [];
72	    for (const f of files) {
73	      lines.push({ text: f.title, tone: "muted" });
74	      for (const l of f.lines.slice(0, 8)) {
75	        lines.push({ text: `${l.kind === "added" ? "+" : l.kind === "removed" ? "-" : " "} ${l.content}`, tone: l.kind === "added" ? "added" : "muted" });
76	      }
77	    }
78	    if (!lines.length) lines.push({ text: "No patch was recorded for this run." });
79	    add("Repair attempts", attempts.length || null);
80	    add("Files changed", files.length || null);
81	    add("Lines added", files.reduce((n, f) => n + f.lines.filter((l) => l.kind === "added").length, 0) || null);
82	    return { title: `${r.repo} · repair`, lines, stats };
83	  }
84	
85	  const v = r.verifier?.steps ?? [];
86	  const lines: Line[] = v.length
87	    ? v.map((s) => ({ text: `${stepOk(s) ? "✓" : "✗"} ${s.name}  ${fmtDur(s.duration_s)}`, tone: stepOk(s) ? ("good" as const) : ("bad" as const) }))
88	    : [{ text: "The clean container was never reached for this run." }];
89	  add("Clean-container steps passed", v.length ? `${v.filter(stepOk).length} of ${v.length}` : null);
90	  add("Time in the clean container", v.length ? fmtDur(v.reduce((a, s) => a + (s.duration_s ?? 0), 0)) : null);
91	  add("Verdict", statusMeta(d.summary.status).word);
92	  return { title: `${r.repo} · clean container`, lines, stats };
93	}
