95	/** Check, Diagnose, Repair, Prove: each tab streams a real excerpt and shows real stat cards. */
96	export function SolutionTabs({ detail }: { detail: RunDetail }) {
97	  const reduce = useReducedMotion();
98	  const [tab, setTab] = useState<TabKey>("check");
99	  const [manual, setManual] = useState(false);
100	  const [held, setHeld] = useState(false);
101	  const [inView, setInView] = useState(false);
102	  const box = useRef<HTMLDivElement>(null);
103	
104	  useEffect(() => {
105	    const el = box.current;
106	    if (!el || typeof IntersectionObserver === "undefined") return;
107	    const io = new IntersectionObserver(([e]) => setInView(e.isIntersecting), { threshold: 0.3 });
108	    io.observe(el);
109	    return () => io.disconnect();
110	  }, []);
111	
112	  // Anticipation: the tab indicator moves first; the content swaps ~160 ms later.
113	  const [shownTab, setShownTab] = useState<TabKey>(tab);
114	  useEffect(() => {
115	    if (reduce) {
116	      setShownTab(tab);
117	      return;
118	    }
119	    const id = window.setTimeout(() => setShownTab(tab), 160);
120	    return () => window.clearTimeout(id);
121	  }, [tab, reduce]);
122	
123	  const c = useMemo(() => contentFor(shownTab, detail), [shownTab, detail]);
124	  const joined = c.lines.map((l) => l.text).join("\n");
125	  const { shown, done } = useStream(joined, { restartKey: shownTab, enabled: inView || manual });
126	
127	  // Stay long enough to read what streamed, plus the stat labels: 250 ms and 30 ms a word.
128	  const readMs = Math.max(1800, readingMs(`${joined} ${c.stats.map((s) => `${s.label} ${s.value}`).join(" ")}`));
129	  useEffect(() => {
130	    if (reduce || manual || held || !done || !inView || shownTab !== tab) return;
131	    const i = TABS.findIndex((t) => t.id === tab);
132	    const id = window.setTimeout(() => setTab(TABS[(i + 1) % TABS.length].id), readMs);
133	    return () => window.clearTimeout(id);
134	  }, [reduce, manual, held, done, inView, tab, shownTab, readMs]);
135	
136	  const visible = shown.split("\n");
137	
138	  return (
139	    <div
140	      ref={box}
141	      className="mt-12 grid gap-8 lg:grid-cols-[18rem_minmax(0,1fr)]"
142	      onMouseEnter={() => setHeld(true)}
143	      onMouseLeave={() => setHeld(false)}
144	      onFocus={() => setHeld(true)}
145	      onBlur={() => setHeld(false)}
146	    >
147	      <TabList
148	        prefix="sol"
149	        label="Stages"
150	        orientation="vertical"
151	        tabs={TABS}
152	        value={tab}
153	        onChange={(id, byUser) => {
154	          if (byUser) setManual(true);
155	          setTab(id);
156	        }}
157	        className="flex gap-2 overflow-x-auto lg:flex-col"
158	        tabClassName={(sel) =>
159	          cn(
160	            "chip-t flex min-w-40 items-start gap-3 rounded-lg border px-4 py-3 text-left",
161	            sel ? "border-accent-strong bg-panel" : "border-transparent text-muted-foreground hover:bg-panel",
162	          )
163	        }
164	        render={(t) => {
165	          const tt = TABS.find((x) => x.id === t.id)!;
166	          return (
167	            <>
168	              <AnimIcon name={tt.icon} className="mt-0.5 size-5 shrink-0" />
169	              <span>
170	                <span className="block font-semibold text-foreground">{tt.label}</span>
171	                <span className="mt-0.5 hidden text-sm lg:block">{tt.blurb}</span>
172	              </span>
173	            </>
174	          );
175	        }}
176	      />
177	      <div role="tabpanel" id={panelId("sol", tab)} aria-labelledby={tabId("sol", tab)} className="min-w-0 rounded-xl border border-border bg-panel p-4 sm:p-6">
178	        <div className="overflow-hidden rounded-lg border border-border bg-terminal text-terminal-ink">
179	          <p className="border-b border-border bg-panel px-3 py-2 font-mono text-xs text-muted-foreground">{c.title}</p>
180	          <pre className="m-0 min-h-[10rem] overflow-x-auto whitespace-pre-wrap break-words p-3 font-mono text-[13px] leading-relaxed">
181	            {visible.map((t, i) => {
182	              const tone = c.lines[i]?.tone;
183	              return (
184	                <span
185	                  key={i}
186	                  className={cn(
187	                    "block",
188	                    tone === "bad" && "text-broken",
189	                    tone === "good" && "text-runs",
190	                    tone === "muted" && "text-muted-foreground",
191	                    tone === "added" && "bg-evidence text-on-evidence",
192	                  )}
193	                >
194	                  {t || " "}
195	                  {i === visible.length - 1 && !done && <span className="stream-cursor" />}
196	                </span>
197	              );
198	            })}
199	          </pre>
200	        </div>
201	        {c.stats.length > 0 && (
202	          <dl className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
203	            {c.stats.map((s, i) => (
204	              // Follow-through: the stat cards trail the excerpt, one after another.
205	              <div
206	                key={`${shownTab}-${s.label}`}
207	                style={{ "--i": i + 1 } as CSSProperties}
208	                className="settle rounded-lg border border-border bg-canvas p-4"
209	              >
210	                <dd className="font-mono text-2xl font-semibold tabular-nums">{s.value}</dd>
211	                <dt className="mt-1 text-sm text-muted-foreground">{s.label}</dt>
212	              </div>
213	            ))}
214	          </dl>
215	        )}
216	        <p className="mt-3 text-xs text-muted-foreground">
217	          {reduce ? "" : manual ? "" : "Advances on its own. Select a tab to hold it. "}
218	          Excerpts and numbers are read from the recorded run of {detail.result.repo}.
219	        </p>
220	      </div>
221	    </div>
222	  );
223	}
