/*
 * The beam (How it works): one beam runs the connector between the four stage tabs, once, then the
 * connector holds its drawn state. SolutionTabs writes --beam (0 to 1) on the connector's wrapper;
 * a segment shows its third of it (--i is the stage it leaves) and a node fills as the beam leaves it.
 * Below lg the connector runs sideways above the tabs; from lg it runs down the left of the list.
 * Geometry is measured from each tab's padding box: node centres sit 26 px along, 11 px (or 13 px) outside.
 */
.beam-seg,
.beam-node {
  position: absolute;
  pointer-events: none;
  --l: clamp(0, calc(var(--beam, 0) * 3 - var(--i)), 1);
}
.beam-seg {
  left: 26px;
  top: -12px;
  width: calc(100% + 10px);
  height: 2px;
  border-radius: 1px;
  background: var(--hairline);
}
.beam-fill {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: var(--accent-strong);
  transform-origin: 0 0;
  scale: var(--l) 1;
}
/* The bright head of the beam, only while it is inside this segment. */
.beam-head {
  position: absolute;
  top: -1px;
  left: calc(var(--l) * 100%);
  width: 28px;
  height: 4px;
  margin-left: -28px;
  border-radius: 2px;
  background: linear-gradient(to right, transparent, var(--accent));
  box-shadow: 0 0 8px var(--accent);
  opacity: calc(min(1, var(--l) * 24) * min(1, (1 - var(--l)) * 24));
}
.beam-node {
  left: 21px;
  top: -16px;
  z-index: 1;
  width: 10px;
  height: 10px;
  border-radius: 9999px;
  border: 2px solid var(--control);
  background: var(--canvas);
  --l: clamp(0, calc((var(--beam, 0) * 3 - var(--i)) * 10), 1);
}
.beam-node-fill {
  position: absolute;
  inset: -2px;
  border-radius: inherit;
  background: var(--accent-strong);
  scale: var(--l);
}
@media (min-width: 64rem) {
  .beam-seg { left: -14px; top: 26px; width: 2px; height: calc(100% + 10px); }
  .beam-fill { scale: 1 var(--l); }
