// Close-ups for the polish pass. Usage: node shots.mjs <outDir>
import { spawn } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const base = "http://REDACTED:8787";
const outDir = process.argv[2];
mkdirSync(outDir, { recursive: true });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const port = 9900 + Math.floor(Math.random() * 90);
const proc = spawn("chromium", ["--headless=new", "--disable-gpu", "--no-sandbox", `--remote-debugging-port=${port}`, `--user-data-dir=${join(outDir, ".profile")}`, "about:blank"], { stdio: "ignore" });
let tab;
for (let i = 0; i < 50 && !tab; i++) {
  try { tab = (await (await fetch(`http://REDACTED:${port}/json`)).json()).find((t) => t.type === "page"); } catch {}
  if (!tab) await sleep(200);
}
const ws = new WebSocket(tab.webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));
let n = 0;
const waiting = new Map();
let synthetic = false;
ws.onmessage = async (m) => {
  const d = JSON.parse(m.data);
  if (d.id && waiting.has(d.id)) return waiting.get(d.id)(d);
  if (d.method === "Fetch.requestPaused") {
    const { requestId, request } = d.params;
    const path = new URL(request.url).pathname;
    if (!synthetic || path !== "/api/runs") return void send("Fetch.continueRequest", { requestId });
    const body = await send("Fetch.getResponseBody", { requestId });
    const list = JSON.parse(Buffer.from(body.result.body, "base64").toString());
    const src = list.find((r) => r.status === "runs" && r.fix_kind) ?? list[0];
    const fake = { ...src, id: "20261010T000000Z-aaaaaaa", repo: "example/awaiting-approval-sample", path: null, status: "fix_awaiting_approval", needs_approval: true, fix_kind: "code" };
    list.unshift(fake);
    await send("Fetch.fulfillRequest", {
      requestId, responseCode: 200,
      responseHeaders: [{ name: "content-type", value: "application/json" }],
      body: Buffer.from(JSON.stringify(list)).toString("base64"),
    });
  }
};
const send = (method, params = {}) => new Promise((res) => { waiting.set(++n, res); ws.send(JSON.stringify({ id: n, method, params })); });
const value = async (expr) => (await send("Runtime.evaluate", { expression: expr, returnByValue: true })).result.result.value;
await send("Fetch.enable", { patterns: [{ urlPattern: "*/api/runs*", requestStage: "Response" }] });

const open = async (width, theme, { reduce = false, fake = false, height = 900 } = {}) => {
  synthetic = fake;
  await send("Emulation.setDeviceMetricsOverride", { width, height, deviceScaleFactor: 1, mobile: false });
  await send("Emulation.setEmulatedMedia", { features: [{ name: "prefers-color-scheme", value: theme }, { name: "prefers-reduced-motion", value: reduce ? "reduce" : "no-preference" }] });
  await send("Page.navigate", { url: base + "/" });
  await sleep(3000);
};
const shot = async (file, selectorJs, pad = 12) => {
  // Scroll the element to the middle, then clip its box (page coordinates).
  const r = JSON.parse(await value(`(() => { const e = ${selectorJs}; if (!e) return 'null'; e.scrollIntoView({ block: 'center' }); const b = e.getBoundingClientRect();
    return JSON.stringify({ x: b.left + scrollX, y: b.top + scrollY, w: b.width, h: b.height }); })()`));
  if (!r) return console.log("MISSING", file);
  await sleep(150);
  const clip = { x: Math.max(0, r.x - pad), y: Math.max(0, r.y - pad), width: r.w + pad * 2, height: r.h + pad * 2, scale: 1 };
  const res = await send("Page.captureScreenshot", { format: "png", clip, captureBeyondViewport: true });
  const p = join(outDir, file);
  writeFileSync(p, Buffer.from(res.result.data, "base64"));
  console.log("shot", p);
};
const TABS = `document.querySelector('[role=tablist][aria-label=Stages]').parentElement.parentElement`;
const STATS = `[...document.querySelectorAll('dl')].find((d) => /Repos checked/.test(d.textContent)).parentElement`;
const DDS = `JSON.stringify([...document.querySelectorAll('dl dd')].filter((d) => /Repos checked|Verified in a clean|Median wall/.test(d.nextElementSibling?.textContent ?? '')).map((d) => d.innerText.replace(/\\s+/g, ' ') + ' | ' + d.nextElementSibling.textContent))`;
const BEAM = `getComputedStyle(document.querySelector('[role=tablist][aria-label=Stages]').parentElement).getPropertyValue('--beam')`;

for (const theme of ["light", "dark"]) {
  for (const width of [420, 1280]) {
    await open(width, theme, { fake: true });
    // Beam: bring the tab list into view, let it run, then close-up of the drawn connector.
    await value(`document.querySelector('[role=tablist][aria-label=Stages]').scrollIntoView({ block: 'center' })`);
    if (theme === "light" && width === 1280) {
      await sleep(1100 + 700 + 400);
      await shot(`beam-mid-${width}-${theme}.png`, TABS);
      console.log("beam value mid:", await value(BEAM));
    }
    await sleep(5000);
    console.log(`beam ${width} ${theme}:`, await value(BEAM));
    await shot(`beam-${width}-${theme}.png`, TABS);
    // Stats: ticker starts once the stats are in view and the beam is done.
    await value(`(${STATS}).scrollIntoView({ block: 'center' })`);
    await sleep(300);
    const early = await value(DDS);
