    await shot(`legend-${width}-${theme}.png`, `[...document.querySelectorAll('p')].find((p) => /Fix verified · awaiting approval/.test(p.textContent) && /Runs with gaps/.test(p.textContent))`, 16);
    await shot(`works-with-${width}-${theme}.png`, `document.querySelector('section[aria-label="Works with"]')`, 24);
    await shot(`built-with-${width}-${theme}.png`, `document.querySelector('section[aria-label="Built with"]')`, 24);
  }
}

// Wide viewport: the background art sits in the margin, never in the column.
for (const theme of ["light", "dark"]) {
  await open(1700, theme, { height: 1000 });
  const res = await send("Page.captureScreenshot", { format: "png" });
  writeFileSync(join(outDir, `art-top-1700-${theme}.png`), Buffer.from(res.result.data, "base64"));
  await value(`document.querySelector('section[aria-label="Works with"]').scrollIntoView({ block: 'center' })`);
  await sleep(600);
  const res2 = await send("Page.captureScreenshot", { format: "png" });
  writeFileSync(join(outDir, `art-works-with-1700-${theme}.png`), Buffer.from(res2.result.data, "base64"));
  console.log("art shots", theme);
}

// Reduced motion: final numbers at once, connector already drawn.
await open(1280, "light", { reduce: true });
await value(`document.querySelector('[role=tablist][aria-label=Stages]').scrollIntoView({ block: 'center' })`);
await sleep(500);
console.log("reduced: beam", await value(BEAM));
await value(`(${STATS}).scrollIntoView({ block: 'center' })`);
await sleep(300);
console.log("reduced: stats", await value(DDS));

// Hero: skeleton at the same size as the story. Read the hero column height right after the first paint and when settled.
synthetic = false;
await send("Emulation.setEmulatedMedia", { features: [{ name: "prefers-color-scheme", value: "light" }, { name: "prefers-reduced-motion", value: "no-preference" }] });
for (const width of [420, 1280]) {
  await send("Emulation.setDeviceMetricsOverride", { width, height: 900, deviceScaleFactor: 1, mobile: false });
  await send("Page.navigate", { url: base + "/" });
