  const seen = [];
  for (let i = 0; i < 30; i++) { seen.push(await value(H)); await sleep(100); }
  await sleep(4000);
  seen.push(await value(H));
  console.log(`hero section height over time at ${width}:`, seen.join(","));
}
ws.close();
proc.kill();

